{"command":"cat << 'EOF' > /workspace/internal/config/config.go
package config

import (
	"os"

	"gopkg.in/yaml.v3"
)

type AllowRule struct {
	To     []string `yaml:"to"`
	Reason string   `yaml:"reason"`
}

func (r *AllowRule) UnmarshalYAML(node *yaml.Node) error {
	var list []string
	if err := node.Decode(&list); err == nil {
		r.To = list
		return nil
	}
