{"command":"cat << 'EOF' > /workspace/internal/graph/glob.go
package graph

import (
	"regexp"
	"strings"
)

func GlobToRegex(pattern string) *regexp.Regexp {
	pattern = strings.ReplaceAll(pattern, "\\", "/")
	if strings.HasPrefix(pattern, "./") {
		pattern = pattern[2:]
	}

	var sb strings.Builder
	sb.WriteString("^")

	i := 0
	n := len(pattern)
	for i < n {
		if i+1 < n && pattern[i:i+2] == "**" {
			if i+2 < n && pattern[i+2] == '/' {
				sb.WriteString("(?:.*/)?")
				i += 3
			} else if i > 0 && pattern[i-1] == '/' {
				sb.WriteString(".*")
				i += 2
			} else {
				sb.WriteString(".*")
				i += 2
			}
			continue
		}
		c := pattern[i]
		switch c {
		case '*':
			sb.WriteString("[^/]*")
		case '?':
			sb.WriteString("[^/]")
		case '.', '+', '(', ')', '|', '^', '$', '[', ']', '{', '}', '\\':
			sb.WriteString("\\")
			sb.WriteByte(c)
		default:
			sb.WriteByte(c)
		}
		i++
	}
	sb.WriteString("$")

	re, err := regexp.Compile(sb.String())
	if err != nil {
		return regexp.MustCompile("^$")
	}
	return re
}

func MatchGlob(pattern string, filePath string) bool {
	filePath = strings.ReplaceAll(filePath, "\\", "/")
	if strings.HasPrefix(filePath, "./") {
		filePath = filePath[2:]
	}
	re := GlobToRegex(pattern)
	return re.MatchString(filePath)
}

func MatchAnyGlob(patterns []string, filePath string) bool {
	for _, p := range patterns {
		if MatchGlob(p, filePath) {
			return true
		}
	}
	return false
}

func ExpandAliases(patterns []string, aliases map[string][]string) []string {
	var result []string
	for _, p := range patterns {
		if expanded, ok := aliases[p]; ok {
			result = append(result, ExpandAliases(expanded, aliases)...)
		} else {
			result = append(result, p)
		}
	}
	return result
}
EOF"}

