{"command":"cat << 'EOF' > /workspace/internal/graph/root.go
package graph

import (
	"os"
	"path/filepath"
)

var rootIndicators = []string{
	".dep-tree.yml",
	".git",
	"package.json",
	"go.mod",
	"Cargo.toml",
	"pyproject.toml",
	"setup.py",
	"requirements.txt",
}

func FindRoot(entrypoint string) string {
	abs, err := filepath.Abs(entrypoint)
	if err != nil {
		abs = entrypoint
	}
	dir := abs
	fi, err := os.Stat(abs)
	if err == nil && !fi.IsDir() {
		dir = filepath.Dir(abs)
	}

	current := dir
	var firstFound string

	for {
		for _, ind := range rootIndicators {
			if _, err := os.Stat(filepath.Join(current, ind)); err == nil {
				if firstFound == "" {
					firstFound = current
				}
				// If .git or .dep-tree.yml is found, this is the project root
				if ind == ".git" || ind == ".dep-tree.yml" {
					return current
				}
			}
		}
		parent := filepath.Dir(current)
		if parent == current {
			break
		}
		current = parent
	}

	if firstFound != "" {
		return firstFound
	}
	return dir
}
EOF"}

