{"command":"cat << 'EOF' > /workspace/internal/parser/parser.go
package parser

import (
	"fmt"
	"path/filepath"
	"strings"

	"dep-tree/internal/config"
)

type Language interface {
	ParseImports(filePath string, rootDir string, cfg *config.Config) ([]string, error)
}

func IsSupportedLanguage(filePath string) bool {
	ext := strings.ToLower(filepath.Ext(filePath))
	switch ext {
	case ".js", ".jsx", ".ts", ".tsx", ".mjs", ".cjs", ".py", ".go", ".rs":
		return true
	default:
		if strings.HasSuffix(filePath, ".d.ts") {
			return true
		}
		return false
	}
}

func GetLanguage(filePath string) (Language, error) {
	ext := strings.ToLower(filepath.Ext(filePath))
	if strings.HasSuffix(filePath, ".d.ts") {
		return &JSLanguage{}, nil
	}
	switch ext {
	case ".js", ".jsx", ".ts", ".tsx", ".mjs", ".cjs":
		return &JSLanguage{}, nil
	case ".py":
		return &PythonLanguage{}, nil
	case ".go":
		return &GoLanguage{}, nil
	case ".rs":
		return &RustLanguage{}, nil
	default:
		return nil, fmt.Errorf("none of the provided files belong to the a supported language")
	}
}
EOF"}

