{"command":"cat << 'EOF' > /workspace/internal/parser/python.go
package parser

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"

	"dep-tree/internal/config"
)

type PythonLanguage struct{}

var (
	pyFromImportRegex = regexp.MustCompile(`^\s*from\s+([.\w]+)\s+import\s+`)
	pyImportRegex     = regexp.MustCompile(`^\s*import\s+(.+)`)
)

func (l *PythonLanguage) ParseImports(filePath string, rootDir string, cfg *config.Config) ([]string, error) {
	file, err := os.Open(filePath)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	var resolvedFiles []string
	var errs []string

	dir := filepath.Dir(filePath)

	for scanner.Scan() {
		line := scanner.Text()
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}

		if cfg.Python.ExcludeConditionalImports {
			// If line starts with whitespace / indentation, skip conditional import
			if len(line) > len(strings.TrimLeft(line, " \t")) {
				continue
			}
		}

		if m := pyFromImportRegex.FindStringSubmatch(line); len(m) > 1 {
			mod := m[1]
			res, err := resolvePyImport(mod, dir, rootDir)
			if err != nil {
				errs = append(errs, err.Error())
			} else if res != "" {
				resolvedFiles = append(resolvedFiles, res)
			}
		} else if m := pyImportRegex.FindStringSubmatch(line); len(m) > 1 {
			mods := strings.Split(m[1], ",")
			for _, item := range mods {
				mod := strings.Fields(strings.TrimSpace(item))[0]
				res, err := resolvePyImport(mod, dir, rootDir)
				if err != nil {
					errs = append(errs, err.Error())
				} else if res != "" {
					resolvedFiles = append(resolvedFiles, res)
				}
			}
		}
	}

	if len(errs) > 0 {
		return resolvedFiles, fmt.Errorf("%s", strings.Join(errs, "\n"))
	}
	return resolvedFiles, nil
}

func resolvePyImport(spec string, currentDir string, rootDir string) (string, error) {
	if strings.HasPrefix(spec, ".") {
		// Relative import
		dots := 0
		for i < len(spec) && spec[i] == '.' {
			dots++
			i++
		}
		rest := spec[dots:]

		baseDir := currentDir
		for d := 1; d < dots; d++ {
			baseDir = filepath.Dir(baseDir)
		}

		restPath := strings.ReplaceAll(rest, ".", "/")
		candidate := filepath.Join(baseDir, restPath)

		if resolved, ok := checkPyPath(candidate); ok {
			return resolved, nil
		}
		return "", fmt.Errorf("could not resolve relative import from %s to %s", currentDir, candidate)
	}

	// Absolute import
	restPath := strings.ReplaceAll(spec, ".", "/")
	candidate := filepath.Join(rootDir, restPath)
	if resolved, ok := checkPyPath(candidate); ok {
		return resolved, nil
	}
	candidateCurr := filepath.Join(currentDir, restPath)
	if resolved, ok := checkPyPath(candidateCurr); ok {
		return resolved, nil
	}

	// If not found locally, treat as stdlib / third-party (return "")
	return "", nil
}

var i int

func checkPyPath(base string) (string, bool) {
	p1 := base + ".py"
	if fi, err := os.Stat(p1); err == nil && !fi.IsDir() {
		return filepath.Clean(p1), true
	}
	p2 := filepath.Join(base, "__init__.py")
	if fi, err := os.Stat(p2); err == nil && !fi.IsDir() {
		return filepath.Clean(p2), true
	}
	return "", false
}
EOF"}

