	"dep-tree/internal/config"
)

type GoLanguage struct{}

func (l *GoLanguage) ParseImports(filePath string, rootDir string, cfg *config.Config) ([]string, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filePath, nil, parser.ImportsOnly)
	if err != nil {
		return nil, err
	}

	moduleName := getGoModuleName(rootDir)

	var resolvedFiles []string
	for _, imp := range f.Imports {
		pathVal := strings.Trim(imp.Path.Value, `"`)
		if moduleName != "" && strings.HasPrefix(pathVal, moduleName) {
			relPath := strings.TrimPrefix(pathVal, moduleName)
			targetDir := filepath.Join(rootDir, relPath)
			files, err := os.ReadDir(targetDir)
			if err == nil {
				for _, entry := range files {
					if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".go") && !strings.HasSuffix(entry.Name(), "_test.go") {
						resolvedFiles = append(resolvedFiles, filepath.Join(targetDir, entry.Name()))
					}
				}
			}
		}
	}

	return resolvedFiles, nil
}

func getGoModuleName(rootDir string) string {
	goModPath := filepath.Join(rootDir, "go.mod")
	file, err := os.Open(goModPath)
	if err != nil {
