package render

import (
	"encoding/json"
	"fmt"
	"sort"
	"strings"

	"dep-tree/internal/graph"
)

type TreeJSONOutput struct {
	Tree                 map[string]interface{} `json:"tree"`
	CircularDependencies [][]string             `json:"circularDependencies"`
	Errors               map[string][]string    `json:"errors"`
}

func RenderTreeJSON(g *graph.Graph) (string, error) {
	rootMap := make(map[string]interface{})

	// Find entrypoint nodes
	for _, n := range g.NodeList {
		if n.IsEntrypoint {
			visited := make(map[uint32]bool)
			tree := graph.BuildNestedTree(g, n.ID, visited)
			rootMap[n.RelPath] = tree
		}
	}

	circ := g.CircularDependencies
	if circ == nil {
		circ = [][]string{}
	}

	errs := g.Errors
	if errs == nil {
		errs = make(map[string][]string)
	}

	out := TreeJSONOutput{
		Tree:                 rootMap,
		CircularDependencies: circ,
		Errors:               errs,
	}

	data, err := json.MarshalIndent(out, "", "  ")
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func RenderTreeText(g *graph.Graph) string {
	var sb strings.Builder

	for _, n := range g.NodeList {
		if n.IsEntrypoint {
			visited := make(map[uint32]bool)
			renderTextNode(&sb, g, n.ID, "", true, visited)
		}
	}

	return sb.String()
}

func renderTextNode(sb *strings.Builder, g *graph.Graph, id uint32, indent string, isLast bool, visited map[uint32]bool) {
	node, ok := g.Nodes[id]
	if !ok {
		return
	}

	if indent == "" {
		sb.WriteString(node.RelPath)
		sb.WriteString("\n")
	} else {
		sb.WriteString(indent)
		if isLast {
			sb.WriteString("└▷")
		} else {
			sb.WriteString("├▷")
		}
		sb.WriteString(node.RelPath)
		sb.WriteString("\n")
	}

	if visited[id] {
		return
	}
	visited[id] = true

	children := g.Adjacency[id]
	sort.Slice(children, func(i, j int) bool {
		n1 := g.Nodes[children[i]]
		n2 := g.Nodes[children[j]]
		if n1 == nil || n2 == nil {
			return children[i] < children[j]
		}
		return n1.RelPath < n2.RelPath
	})

	childIndent := indent
	if indent != "" {
		if isLast {
			childIndent += "  "
		} else {
			childIndent += "│ "
		}
	} else {
		childIndent = "│\n"
	}

	for i, childID := range children {
		isChildLast := (i == len(children)-1)
		renderTextNode(sb, g, childID, strings.TrimSuffix(childIndent, "\n"), isChildLast, visited)
	}

	visited[id] = false
}
EOF"}

