package render

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"dep-tree/internal/graph"
)

//go:embed template.html
var templateHTML string

type EntropyPayload struct {
	Nodes     []*graph.Node `json:"nodes"`
	Links     []graph.Link  `json:"links"`
	EnableGui bool          `json:"enableGui"`
}

func RenderEntropy(g *graph.Graph, renderPath string, enableGui bool) (string, error) {
	if renderPath == "" {
		renderPath = filepath.Join(os.TempDir(), "index.html")
	}

	nodes := g.NodeList
	if nodes == nil {
		nodes = []*graph.Node{}
	}
	links := g.Links
	if links == nil {
		links = []graph.Link{}
	}

	payload := EntropyPayload{
		Nodes:     nodes,
		Links:     links,
		EnableGui: enableGui,
	}

	jsonBytes, err := json.Marshal(payload)
	if err != nil {
		return "", err
	}

	html := strings.Replace(templateHTML, "__GRAPH_DATA_PLACEHOLDER__", string(jsonBytes), 1)

	err = os.WriteFile(renderPath, []byte(html), 0644)
	if err != nil {
		return "", err
	}

	return renderPath, nil
}
EOF"}

