package cmd

import (
	"fmt"
	"os"

	"github.com/spf13/cobra"

	"dep-tree/internal/config"
)

var (
	cfgFile                     string
	unwrapExports               bool
	jsTsConfigPaths             bool
	jsWorkspaces                bool
	pythonExcludeCondImports   bool
	onlyFlags                   []string
	excludeFlags                []string
	versionFlag                 bool
)

var banner = `
      ____         _ __       _
     |  _ \   ___ |  _ \    _| |_  _ __  ___   ___
     | | | | / _ \| |_) |  |_   _||  __|/ _ \ / _ \
     | |_| ||  __/| .__/     | |  | |  |  __/|  __/
     |____/  \__| |_|        | \__|_|   \___| \___|
`

var RootCmd = &cobra.Command{
	Use:   "dep-tree [command]",
	Short: "Visualize your dependencies graphically",
	Long:  banner,
	Example: `$ dep-tree src/index.ts
$ dep-tree entropy src/index.ts
$ dep-tree tree package/main.py --unwrap-exports
$ dep-tree check`,
	RunE: func(cmd *cobra.Command, args []string) error {
		if versionFlag {
			fmt.Println("dep-tree version v0.23.4")
			return nil
		}
		if len(args) > 0 {
			return entropyCmd.RunE(cmd, args)
		}
		return cmd.Help()
	},
}

func Execute() {
	RootCmd.SetHelpTemplate(banner + "\n" + RootCmd.HelpTemplate())
	if err := RootCmd.Execute(); err != nil {
		os.Exit(1)
	}
}

func init() {
	RootCmd.PersistentFlags().StringVarP(&cfgFile, "config", "c", ".dep-tree.yml", "path to dep-tree's config file.")
	RootCmd.PersistentFlags().BoolVar(&unwrapExports, "unwrap-exports", false, "trace re-exported symbols to the file where they are declared.")
	RootCmd.PersistentFlags().BoolVar(&jsTsConfigPaths, "js-tsconfig-paths", true, "follow the tsconfig.json paths while resolving imports.")
	RootCmd.PersistentFlags().BoolVar(&jsWorkspaces, "js-workspaces", true, "take the workspaces attribute in the root package.json into account for resolving paths.")
	RootCmd.PersistentFlags().BoolVar(&pythonExcludeCondImports, "python-exclude-conditional-imports", false, "exclude imports wrapped inside if or try statements.")
	RootCmd.PersistentFlags().StringArrayVar(&onlyFlags, "only", nil, "Files that do not match this glob pattern will be ignored. You can provide an arbitrary number of --only flags.")
	RootCmd.PersistentFlags().StringArrayVar(&excludeFlags, "exclude", nil, "Files that match this glob pattern will be ignored. You can provide an arbitrary number of --exclude flags.")
	RootCmd.Flags().BoolVarP(&versionFlag, "version", "v", false, "version for dep-tree")

	RootCmd.AddCommand(entropyCmd)
	RootCmd.AddCommand(treeCmd)
	RootCmd.AddCommand(checkCmd)
	RootCmd.AddCommand(explainCmd)
	RootCmd.AddCommand(configCmd)
}

func loadMergedConfig(cmd *cobra.Command) (config.Config, error) {
	cfg, err := config.LoadConfig(cfgFile)
	if err != nil && cmd.Flags().Changed("config") {
		return cfg, err
	}

	if cmd.Flags().Changed("unwrap-exports") {
		cfg.UnwrapExports = unwrapExports
	}
	if cmd.Flags().Changed("js-tsconfig-paths") {
		cfg.JS.TsConfigPaths = &jsTsConfigPaths
	}
	if cmd.Flags().Changed("js-workspaces") {
		cfg.JS.Workspaces = &jsWorkspaces
	}
	if cmd.Flags().Changed("python-exclude-conditional-imports") {
		cfg.Python.ExcludeConditionalImports = pythonExcludeCondImports
	}
	if len(onlyFlags) > 0 {
		cfg.Only = append(cfg.Only, onlyFlags...)
	}
	if len(excludeFlags) > 0 {
		cfg.Exclude = append(cfg.Exclude, excludeFlags...)
	}

	return cfg, nil
}
EOF"}

