{"command":"cat << 'EOF' > /workspace/cmd/check.go
package cmd

import (
	"fmt"
	"strings"

	"github.com/spf13/cobra"

	"dep-tree/internal/graph"
)

var checkCmd = &cobra.Command{
	Use:   "check [flags]",
	Short: "Checks that the dependency rules defined in the configuration file are not broken",
	RunE: func(cmd *cobra.Command, args []string) error {
		cfg, err := loadMergedConfig(cmd)
		if err != nil {
			return err
		}

		if len(cfg.Check.Entrypoints) == 0 {
			return fmt.Errorf("no entrypoints provided in check configuration")
		}

		g, err := graph.BuildGraph(cfg.Check.Entrypoints, &cfg)
		if err != nil {
			return err
		}

		var violations []string

		// Check circular dependencies
		if !cfg.Check.AllowCircularDependencies && len(g.CircularDependencies) > 0 {
			var circLines []string
			circLines = append(circLines, "detected circular dependencies:")
			for _, cycle := range g.CircularDependencies {
				circLines = append(circLines, "- "+strings.Join(cycle, " -> "))
			}
			violations = append(violations, strings.Join(circLines, "\n"))
		}

		// Check allow & deny rules
		for fromID, children := range g.Adjacency {
			fromNode := g.Nodes[fromID]
			if fromNode == nil {
				continue
			}

			for _, toID := range children {
				toNode := g.Nodes[toID]
				if toNode == nil {
					continue
				}

				// Check deny rules
				for denyPattern, denyRules := range cfg.Check.Deny {
					if graph.MatchGlob(denyPattern, fromNode.RelPath) {
						for _, rule := range denyRules {
							targetGlobs := graph.ExpandAliases([]string{rule.To}, cfg.Check.Aliases)
							if graph.MatchAnyGlob(targetGlobs, toNode.RelPath) {
								msg := fmt.Sprintf("- %s -> %s", fromNode.RelPath, toNode.RelPath)
								if rule.Reason != "" {
									msg += "\n  " + rule.Reason
								}
								violations = append(violations, msg)
							}
						}
					}
				}

				// Check allow rules
				for allowPattern, allowRule := range cfg.Check.Allow {
					if graph.MatchGlob(allowPattern, fromNode.RelPath) {
						allowedGlobs := graph.ExpandAliases(allowRule.To, cfg.Check.Aliases)
						if !graph.MatchAnyGlob(allowedGlobs, toNode.RelPath) {
							msg := fmt.Sprintf("- %s -> %s", fromNode.RelPath, toNode.RelPath)
							if allowRule.Reason != "" {
								msg += "\n  " + allowRule.Reason
							}
							violations = append(violations, msg)
						}
					}
				}
			}
		}

		if len(violations) > 0 {
			return fmt.Errorf("Check failed, the following dependencies are not allowed:\n%s", strings.Join(violations, "\n"))
		}

		return nil
	},
}
EOF"}

