				if mapped := resolveWorkspacePath(spec, rootDir); mapped != "" {
					resolvedFiles = append(resolvedFiles, mapped)
					continue
				}
			}
		}
	}

	if len(errs) > 0 {
		return resolvedFiles, fmt.Errorf("%s", strings.Join(errs, "\n"))
	}
	return resolvedFiles, nil
}

func extractJSSpecifiers(code string) []string {
	seen := make(map[string]bool)
	var specifiers []string

	for _, re := range importRegexes {
		matches := re.FindAllStringSubmatch(code, -1)
		for _, m := range matches {
			if len(m) > 1 {
				spec := m[1]
				if !seen[spec] {
					seen[spec] = true
					specifiers = append(specifiers, spec)
				}
			}
		}
	}
	return specifiers
}

func resolveJSPath(base string) (string, error) {
	fi, err := os.Stat(base)
	if err == nil && !fi.IsDir() {
		return filepath.Clean(base), nil
	}

	for _, ext := range jsExtensions {
		p := base + ext
		if fi, err := os.Stat(p); err == nil && !fi.IsDir() {
			return filepath.Clean(p), nil
		}
	}

	for _, ext := range jsExtensions {
		p := filepath.Join(base, "index"+ext)
		if fi, err := os.Stat(p); err == nil && !fi.IsDir() {
			return filepath.Clean(p), nil
		}
	}

	return "", os.ErrNotExist
}

type TSConfig struct {
	CompilerOptions struct {
		BaseUrl string              `json:"baseUrl"`
		Paths   map[string][]string `json:"paths"`
	} `json:"compilerOptions"`
}

func resolveTSConfigPath(spec string, rootDir string) string {
	tsConfigPath := filepath.Join(rootDir, "tsconfig.json")
	data, err := os.ReadFile(tsConfigPath)
	if err != nil {
		return ""
	}

	var tsConfig TSConfig
	if err := json.Unmarshal(data, &tsConfig); err != nil {
		return ""
	}

	baseUrl := tsConfig.CompilerOptions.BaseUrl
	if baseUrl == "" {
		baseUrl = "."
	}
	baseDir := filepath.Join(rootDir, baseUrl)

	for pattern, targets := range tsConfig.CompilerOptions.Paths {
		for _, target := range targets {
			if strings.HasSuffix(pattern, "/*") {
				prefix := strings.TrimSuffix(pattern, "/*")
				if strings.HasPrefix(spec, prefix+"/") || spec == prefix {
					rest := strings.TrimPrefix(spec, prefix+"/")
					targetPrefix := strings.TrimSuffix(target, "/*")
					candidateBase := filepath.Join(baseDir, targetPrefix, rest)
					if resolved, err := resolveJSPath(candidateBase); err == nil {
						return resolved
					}
				}
			} else if pattern == spec {
				candidateBase := filepath.Join(baseDir, target)
				if resolved, err := resolveJSPath(candidateBase); err == nil {
					return resolved
				}
			}
		}
	}

	return ""
}

type PackageJSON struct {
	Name       string   `json:"name"`
	Main       string   `json:"main"`
	Workspaces []string `json:"workspaces"`
}

func resolveWorkspacePath(spec string, rootDir string) string {
	pkgPath := filepath.Join(rootDir, "package.json")
	data, err := os.ReadFile(pkgPath)
	if err != nil {
		return ""
	}

	var rootPkg PackageJSON
	if err := json.Unmarshal(data, &rootPkg); err != nil {
		return ""
	}

	for _, wsGlob := range rootPkg.Workspaces {
		matches, err := filepath.Glob(filepath.Join(rootDir, wsGlob))
		if err != nil {
			continue
		}
		for _, wsDir := range matches {
			subPkgPath := filepath.Join(wsDir, "package.json")
			subData, err := os.ReadFile(subPkgPath)
			if err != nil {
				continue
			}
			var subPkg PackageJSON
			if err := json.Unmarshal(subData, &subPkg); err == nil {
				if subPkg.Name == spec {
					mainFile := subPkg.Main
					if mainFile == "" {
						mainFile = "index.ts"
					}
					candidate := filepath.Join(wsDir, mainFile)
					if resolved, err := resolveJSPath(candidate); err == nil {
						return resolved
					}
				}
			}
		}
	}

	return ""
}
EOF"}

