	Size         int64    `json:"size"`
	Path         string   `json:"-"`
	RelPath      string   `json:"-"`
}

type Link struct {
	From     uint32 `json:"from"`
	To       uint32 `json:"to"`
	IsCyclic bool   `json:"isCyclic"`
}

type Graph struct {
	Nodes                map[uint32]*Node
	NodeList             []*Node
	Links                []Link
	Adjacency            map[uint32][]uint32
	ReverseAdjacency     map[uint32][]uint32
	Errors               map[string][]string
	CircularDependencies [][]string
	RootDir              string
}

func HashPath(path string) uint32 {
	h := fnv.New32a()
	h.Write([]byte(path))
	return h.Sum32()
}

func BuildGraph(entrypoints []string, cfg *config.Config) (*Graph, error) {
	if len(entrypoints) == 0 {
		return nil, fmt.Errorf("no entrypoints provided")
	}

	for _, ep := range entrypoints {
		if _, err := os.Stat(ep); os.IsNotExist(err) {
			return nil, fmt.Errorf("%s does not match with any existing file", ep)
		}
		if !parser.IsSupportedLanguage(ep) {
			return nil, fmt.Errorf("none of the provided files belong to the a supported language")
		}
	}

	rootDir := FindRoot(entrypoints[0])

	g := &Graph{
		Nodes:            make(map[uint32]*Node),
		Adjacency:        make(map[uint32][]uint32),
		ReverseAdjacency: make(map[uint32][]uint32),
		Errors:           make(map[string][]string),
		RootDir:          rootDir,
	}

	entryMap := make(map[string]bool)
	for _, ep := range entrypoints {
		abs, err := filepath.Abs(ep)
		if err == nil {
			entryMap[abs] = true
		} else {
			entryMap[ep] = true
		}
	}

	visitedStack := make(map[uint32]bool)
	stackPath := []string{}

	var processFile func(filePath string) uint32
	processFile = func(filePath string) uint32 {
		absPath, err := filepath.Abs(filePath)
		if err != nil {
			absPath = filePath
		}
		nodeID := HashPath(absPath)

		relPath, err := filepath.Rel(rootDir, absPath)
		if err != nil {
			relPath = absPath
		}
		relPath = strings.ReplaceAll(relPath, "\\", "/")

		if MatchAnyGlob(cfg.Exclude, relPath) {
			return 0
		}
		if len(cfg.Only) > 0 && !MatchAnyGlob(cfg.Only, relPath) {
			return 0
		}

		if existing, ok := g.Nodes[nodeID]; ok {
			if visitedStack[nodeID] {
				cycle := []string{}
				startIdx := -1
				for idx, p := range stackPath {
					if p == relPath {
						startIdx = idx
						break
					}
				}
				if startIdx != -1 {
					cycle = append(cycle, stackPath[startIdx:]...)
					cycle = append(cycle, relPath)
					g.CircularDependencies = append(g.CircularDependencies, cycle)
				}
			}
			return existing.ID
		}

		content, err := os.ReadFile(absPath)
		loc := 0
		var size int64 = 0
		if err == nil {
			size = int64(len(content))
			if len(content) > 0 {
				loc = bytes.Count(content, []byte("\n")) + 1
			}
		}

		fileName := filepath.Base(absPath)
		dirName := filepath.Dir(relPath)
		if dirName == "." {
			dirName = "./"
		} else {
			dirName = dirName + "/"
		}

		pathBuf := strings.Split(absPath, string(filepath.Separator))
		if len(pathBuf) > 0 && pathBuf[0] == "" {
			pathBuf[0] = ""
		}

		group := ""
		if pkgName := getPackageGroupName(absPath, rootDir); pkgName != "" {
			group = pkgName
		}

		node := &Node{
			ID:           nodeID,
			IsEntrypoint: entryMap[absPath],
			FileName:     fileName,
			PathBuf:      pathBuf,
			Group:        group,
			DirName:      dirName,
			Loc:          loc,
			Size:         size,
			Path:         absPath,
			RelPath:      relPath,
		}

		g.Nodes[nodeID] = node
		g.NodeList = append(g.NodeList, node)

		visitedStack[nodeID] = true
		stackPath = append(stackPath, relPath)

		lang, err := parser.GetLanguage(absPath)
		if err == nil {
			imports, err := lang.ParseImports(absPath, rootDir, cfg)
			if err != nil {
				for _, errLine := range strings.Split(err.Error(), "\n") {
					if strings.TrimSpace(errLine) != "" {
						g.Errors[relPath] = append(g.Errors[relPath], strings.TrimSpace(errLine))
					}
				}
			}

			for _, imp := range imports {
				childID := processFile(imp)
				if childID != 0 {
					g.Adjacency[nodeID] = append(g.Adjacency[nodeID], childID)
					g.ReverseAdjacency[childID] = append(g.ReverseAdjacency[childID], nodeID)

					isCyclic := false
					if visitedStack[childID] {
						isCyclic = true
					}
					g.Links = append(g.Links, Link{
						From:     nodeID,
						To:       childID,
						IsCyclic: isCyclic,
					})
				}
			}
		}

		visitedStack[nodeID] = false
		stackPath = stackPath[:len(stackPath)-1]

		return nodeID
	}

	for _, ep := range entrypoints {
		processFile(ep)
	}

	return g, nil
}

func getPackageGroupName(absPath string, rootDir string) string {
	rel, err := filepath.Rel(rootDir, absPath)
	if err != nil {
		return ""
	}
	parts := strings.Split(rel, string(filepath.Separator))
	if len(parts) > 1 {
		return parts[0]
	}
	return ""
}

func BuildNestedTree(g *Graph, rootID uint32, visited map[uint32]bool) map[string]interface{} {
	_, ok := g.Nodes[rootID]
	if !ok {
		return nil
	}

	if visited[rootID] {
		return nil
	}
	visited[rootID] = true

	children := g.Adjacency[rootID]
	if len(children) == 0 {
		visited[rootID] = false
		return nil
	}

	sort.Slice(children, func(i, j int) bool {
		n1 := g.Nodes[children[i]]
		n2 := g.Nodes[children[j]]
		if n1 == nil || n2 == nil {
			return children[i] < children[j]
		}
		return n1.RelPath < n2.RelPath
	})

	childMap := make(map[string]interface{})
	for _, childID := range children {
		childNode := g.Nodes[childID]
		if childNode == nil {
			continue
		}
		if visited[childID] {
			childMap[childNode.RelPath] = nil
		} else {
			subTree := BuildNestedTree(g, childID, visited)
			childMap[childNode.RelPath] = subTree
		}
	}

	visited[rootID] = false
	return childMap
}
EOF"}

